import * as menu from "@zag-js/menu";
import { positionerStyle } from "marko-zag";
import Icon from "../icon/icon.marko";
import { cn } from "../../../lib/utils.ts";
import type { DropdownMenuItem } from "../dropdown-menu/dropdown-menu.marko";
import Submenu from "./submenu.marko";

// Attr-tag form of DropdownMenuItem. A SINGLE attr tag name (`item`) carries
// all kinds (discriminated by `type`) rather than separate `item`/
// `separator`/`label`/`checkbox`/`radio` attr tags: Marko collects each
// attr-tag NAME into its own independent iterable on `input` with no shared
// ordering between differently-named siblings, so distinct tag names could
// not preserve call-site interleaving. One name with a `type` discriminant
// keeps document order intact by construction (same design as
// dropdown-menu.marko). `content` lets an item or label carry a markup
// body; the plain `label` string renders as the fallback when no body is
// supplied.
//
// `inset` (upstream new styling attr, rule 5) and the checkbox/radio kinds
// are additive here — `DropdownMenuItem` doesn't carry them yet (dropdown-menu
// is a separate re-baseline task), so they're declared locally rather than
// added to the shared type.
export interface MenubarItemAttrs extends DropdownMenuItem {
  content?: Marko.Body;
  /** Upstream styling attr — indents the item to align with checkbox/radio items. */
  inset?: boolean;
  /** `type: "checkbox" | "radio"` checked state (checkbox) or selected value match (radio). */
  checked?: boolean;
  /** Groups radio items — required for `type: "radio"` entries. */
  radioGroup?: string;
  /** `type: "radio"` entries only — this entry's value within its `radioGroup`. */
  radioValue?: string;
  /** `type: "sub"` entries only — the nested submenu's own item list. */
  subEntries?: MenubarItemAttrs[];
}

export interface Input {
  trigger: Marko.Body<[Record<string, unknown>]>;
  items?: DropdownMenuItem[];
  item?: Marko.AttrTag<MenubarItemAttrs>;
  select?: (value: string) => void;
  /** Fires when a checkbox item's checked state changes; receives its value and new checked state. */
  checkedChange?: (value: string, checked: boolean) => void;
  /** Fires when a radio group's selected value changes; receives the group name and new value. */
  radioChange?: (group: string, value: string) => void;
  class?: string;
}

<machine-props/machineProps from=input pick=menu.props
  onSelect(details: menu.SelectionDetails) {
    input.select?.(details.value);
  }/>
<service/service machine=() => menu.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  menu.connect(service, normalizeProps)
  service=service
/>

<const/{ class: className, trigger }=input/>
// Normalize whichever source was supplied into ONE entries list so the
// render path below never branches. Attr tags win when present (compound is
// primary per the compound-tag-dx report); `items=` is the fallback. The
// single `<@item>` tag name preserves true document order by construction,
// so interleaved item/separator/label entries render exactly as written.
// `items=` entries never carry a body, so each is mapped into the
// MenubarItemAttrs shape with an explicit undefined `content` — no casts
// needed (mirrors accordion/toggle-group).
<const/attrItems=[...(input.item ?? [])]/>
<const/entries=(attrItems.length > 0 ? attrItems : (input.items ?? []).map((item) => ({ ...item, content: undefined as Marko.Body | undefined })))/>

// Getter handed to each <Submenu> child so it can call `setParent` on this
// menu's raw service (see submenu.marko for the full wiring rationale).
<const/getOwnService=() => service.service/>

// Trigger is a render-prop (the caller owns the `<button>` markup), so the
// anchor class is offered through the props object like upstream's own
// className default — callers spread it onto their element same as any
// other prop; a caller-supplied `class` in their own JSX wins because it's
// applied after the spread, matching how every other render-prop trigger in
// this registry (popover, hover-card) hands back props without dictating
// element ownership.
<${trigger}({ ...api().getTriggerProps(), "data-slot": "menubar-trigger", class: "hover:bg-muted aria-expanded:bg-muted rounded-2xl px-2 py-0.75 text-sm font-medium flex items-center outline-hidden select-none" })/>
<portal>
  <if=api().open>
    <div ...api().getPositionerProps() style=positionerStyle data-slot="menubar-positioner">
      <div
        ...api().getContentProps()
        data-slot="menubar-content"
        class=cn(
          "bg-popover text-popover-foreground data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/5 dark:ring-foreground/10 min-w-48 rounded-3xl p-1.5 shadow-lg ring-1 duration-100 mu-menu-target mu-menu-translucent z-50 origin-(--radix-menubar-content-transform-origin) overflow-hidden",
          className,
        )
      >
        <for|entry, index| of=entries>
          <const/value=entry.value ?? `item-${index}`/>
          <if=entry.type === "separator">
            <div ...api().getSeparatorProps() data-slot="menubar-separator" class="bg-border/50 -mx-1 my-1 h-px"/>
          </if>
          <else if=entry.type === "label">
            <div data-slot="menubar-label" data-inset=entry.inset || undefined class="text-muted-foreground px-3.5 py-2.5 text-xs data-inset:pl-9.5">
              <if=entry.content>
                <${entry.content}/>
              </if>
              <else>
                ${entry.label}
              </else>
            </div>
          </else>
          <else if=entry.type === "checkbox">
            <div
              ...api().getOptionItemProps({
                type: "checkbox",
                value,
                checked: entry.checked ?? false,
                disabled: entry.disabled,
                onCheckedChange: (checked) => input.checkedChange?.(value, checked),
              })
              data-slot="menubar-checkbox-item"
              data-inset=entry.inset || undefined
              class="focus:bg-accent focus:text-accent-foreground focus:**:text-accent-foreground gap-2.5 rounded-2xl py-2 pr-3 pl-9.5 text-sm font-medium data-inset:pl-9.5 relative flex cursor-default items-center outline-hidden select-none data-[disabled]:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0"
            >
              <span
                ...api().getItemIndicatorProps({ value, checked: entry.checked ?? false })
                data-slot="menubar-checkbox-item-indicator"
                class="left-3 size-4 [&_svg:not([class*='size-'])]:size-4 pointer-events-none absolute flex items-center justify-center"
              >
                <Icon name="Check" aria-hidden="true"/>
              </span>
              <if=entry.content>
                <${entry.content}/>
              </if>
              <else>
                ${entry.label}
              </else>
              <if=entry.shortcut>
                <span data-slot="menubar-shortcut" class="text-muted-foreground group-focus/menubar-item:text-accent-foreground text-xs tracking-widest ml-auto">${entry.shortcut}</span>
              </if>
            </div>
          </else>
          <else if=entry.type === "radio">
            <div
              ...api().getOptionItemProps({
                type: "radio",
                value: entry.radioValue ?? value,
                checked: entry.checked ?? false,
                disabled: entry.disabled,
                onCheckedChange: () => input.radioChange?.(entry.radioGroup ?? "", entry.radioValue ?? value),
              })
              data-slot="menubar-radio-item"
              data-inset=entry.inset || undefined
              class="focus:bg-accent focus:text-accent-foreground focus:**:text-accent-foreground gap-2.5 rounded-2xl py-2 pr-3 pl-9.5 text-sm font-medium data-disabled:opacity-50 data-inset:pl-9.5 [&_svg:not([class*='size-'])]:size-4 relative flex cursor-default items-center outline-hidden select-none data-[disabled]:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0"
            >
              <span
                ...api().getItemIndicatorProps({ value: entry.radioValue ?? value, checked: entry.checked ?? false })
                data-slot="menubar-radio-item-indicator"
                class="left-3 size-4 [&_svg:not([class*='size-'])]:size-4 pointer-events-none absolute flex items-center justify-center"
              >
                <Icon name="Check" aria-hidden="true"/>
              </span>
              <if=entry.content>
                <${entry.content}/>
              </if>
              <else>
                ${entry.label}
              </else>
              <if=entry.shortcut>
                <span data-slot="menubar-shortcut" class="ml-auto">${entry.shortcut}</span>
              </if>
            </div>
          </else>
          <else if=entry.type === "sub">
            <Submenu
              entries=entry.subEntries ?? []
              label=entry.label
              disabled=entry.disabled
              inset=entry.inset
              parent=getOwnService
              onChildReady=(childService) => api().setChild(childService)
            >
              <@trigger|childApi|>
                <div
                  ...api().getTriggerItemProps(childApi)
                  data-slot="menubar-sub-trigger"
                  data-inset=entry.inset || undefined
                  class="focus:bg-accent focus:text-accent-foreground data-open:bg-accent data-open:text-accent-foreground gap-2 rounded-2xl px-3 py-2 text-sm font-medium data-inset:pl-9.5 [&_svg:not([class*='size-'])]:size-4 flex cursor-default items-center outline-none select-none"
                >
                  ${entry.label}
                  <Icon name="ChevronRight" class="mu-rtl-flip ml-auto size-4" aria-hidden="true"/>
                </div>
              </@trigger>
            </Submenu>
          </else>
          <else>
            <div
              ...api().getItemProps({ value, disabled: entry.disabled })
              data-slot="menubar-item"
              data-inset=entry.inset || undefined
              data-variant=entry.variant ?? "default"
              class="focus:bg-accent focus:text-accent-foreground data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 dark:data-[variant=destructive]:focus:bg-destructive/20 data-[variant=destructive]:focus:text-destructive data-[variant=destructive]:*:[svg]:text-destructive! not-data-[variant=destructive]:focus:**:text-accent-foreground gap-2.5 rounded-2xl px-3 py-2 text-sm font-medium data-disabled:opacity-50 data-inset:pl-9.5 [&_svg:not([class*='size-'])]:size-4 group/menubar-item relative flex cursor-default items-center outline-hidden select-none data-[disabled]:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0"
            >
              <if=entry.content>
                <${entry.content}/>
              </if>
              <else>
                ${entry.label}
              </else>
              <if=entry.shortcut>
                <span data-slot="menubar-shortcut" class="ml-auto">${entry.shortcut}</span>
              </if>
            </div>
          </else>
        </for>
      </div>
    </div>
  </if>
</portal>

<return=api>

import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div"> {
  content?: Marko.Body;
}

<const/{ class: className, content, ...rest }=input/>

<div
  data-slot="menubar"
  ...rest
  class=cn("h-9 rounded-3xl border p-1 flex items-center", className)
>
  <${content}/>
</div>

// One nested submenu: a real second `@zag-js/menu` machine instance, linked
// to its parent menu's raw service via `setParent`/`setChild` — the wiring
// zag's own connect() exposes for exactly this (`menu.connect(...).setParent`
// / `.setChild`, both documented to accept the *raw* MarkoService, not the
// connected api — confirmed against `@zag-js/menu@1.43.0`'s connect source).
// Marko gives this its own component instance (and therefore its own
// `<lifecycle>`) per call site, which is exactly the child-machine lifetime
// zag wants — same shape as `<toast-item>`'s per-toast child service linked
// to the toaster's group service.
//
// The trigger row lives in the PARENT menu's item list (it needs the
// parent's `getTriggerItemProps(childApi)`, which only the parent's api
// exposes), so this component renders only the sub-trigger's own subtree:
// the trigger row itself (via `<@trigger>`, receiving this submenu's api so
// the caller can call `getTriggerItemProps`) plus the popped-out content.
// Rendered by `menu.marko` for `type: "sub"` entries. Supports one level of
// nesting (a submenu's own items are flat — item/separator/label only); a
// `type: "sub"` entry inside a submenu's `subEntries` is not wired.
import * as menu from "@zag-js/menu";
import { positionerStyle } from "marko-zag";
import type { MenubarItemAttrs } from "./menu.marko";

export interface Input {
  /** This submenu's own item list — same entry shape as the top-level menu. */
  entries: MenubarItemAttrs[];
  /** Label rendered on the sub-trigger row. */
  label?: string;
  disabled?: boolean;
  inset?: boolean;
  /** Getter for the parent menu's raw service — this submenu registers onto it via `setParent`. */
  parent: () => menu.Service | null;
  /**
   * Fires once this submenu's own raw service exists (on mount), so the
   * parent can complete the link with `parentApi().setChild(childService)` —
   * `setChild` needs the RAW service (see menu.connect's `child.prop("id")`),
   * which only exists after this component's own `<service>` has mounted.
   */
  onChildReady?: (childService: menu.Service) => void;
  /**
   * Trigger render-prop: receives this submenu's connected api so the caller
   * (the parent menu's item loop) can build the row with
   * `parentApi().getTriggerItemProps(childApi)`.
   */
  trigger: Marko.AttrTag<{ content: Marko.Body<[menu.Api]> }>;
}

<machine-props/machineProps from=input pick=menu.props/>
<service/service machine=() => menu.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  menu.connect(service, normalizeProps)
  service=service
/>

// Link this submenu to its parent as soon as both raw services exist.
// `setParent`/`setChild` both take the raw MarkoService (see menu.connect's
// `parent.prop("id")` / `child.prop("id")` calls) — `<service>`'s onMount has
// already run for every ancestor by the time any descendant mounts (Marko
// mounts render bottom-up after the full tree commits), so `input.parent()`
// and `service.service` are both live here.
<lifecycle
  onMount() {
    const parentService = input.parent();
    const ownService = service.service;
    if (!parentService || !ownService) return;
    api().setParent(parentService);
    input.onChildReady?.(ownService);
  }
/>

<${input.trigger.content}(api())/>
<portal>
  <if=api().open>
    <div ...api().getPositionerProps() style=positionerStyle data-slot="menubar-sub-content-positioner">
      <div
        ...api().getContentProps()
        data-slot="menubar-sub-content"
        class="bg-popover text-popover-foreground data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/5 dark:ring-foreground/10 min-w-32 rounded-3xl p-1.5 shadow-lg ring-1 duration-100 mu-menu-target mu-menu-translucent z-50 origin-(--radix-menubar-content-transform-origin) overflow-hidden"
      >
        <for|entry, index| of=input.entries>
          <const/value=entry.value ?? `sub-item-${index}`/>
          <if=entry.type === "separator">
            <div ...api().getSeparatorProps() data-slot="menubar-separator" class="bg-border/50 -mx-1 my-1 h-px"/>
          </if>
          <else if=entry.type === "label">
            <div data-slot="menubar-label" data-inset=entry.inset || undefined class="text-muted-foreground px-3.5 py-2.5 text-xs data-inset:pl-9.5">
              ${entry.label}
            </div>
          </else>
          <else>
            <div
              ...api().getItemProps({ value, disabled: entry.disabled })
              data-slot="menubar-item"
              data-inset=entry.inset || undefined
              data-variant=entry.variant ?? "default"
              class="focus:bg-accent focus:text-accent-foreground data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 dark:data-[variant=destructive]:focus:bg-destructive/20 data-[variant=destructive]:focus:text-destructive data-[variant=destructive]:*:[svg]:text-destructive! not-data-[variant=destructive]:focus:**:text-accent-foreground gap-2.5 rounded-2xl px-3 py-2 text-sm font-medium data-disabled:opacity-50 data-inset:pl-9.5 [&_svg:not([class*='size-'])]:size-4 group/menubar-item relative flex cursor-default items-center outline-hidden select-none data-[disabled]:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0"
            >
              ${entry.label}
              <if=entry.shortcut>
                <span data-slot="menubar-shortcut" class="text-muted-foreground group-focus/menubar-item:text-accent-foreground text-xs tracking-widest ml-auto">${entry.shortcut}</span>
              </if>
            </div>
          </else>
        </for>
      </div>
    </div>
  </if>
</portal>
